import type { ScenarioEmotion } from '../types/course'
import type { Language } from '../i18n/types'
import { saveAsset } from './assets'

// The built-in picture library (public/library/, listed in manifest.json —
// generated by scripts/buildLibraryManifest.mjs). Picking something COPIES the
// files into the project's assets/, so the project stays self-contained and
// exports / offline preview need nothing from the app.

export type Localized = Record<Language, string>

export interface LibraryCharacter {
  id: string
  name: Localized
  role: Localized
  /** Bust portraits (round avatars) by emotion. */
  emotions: string[]
  /** Waist-up scene poses by emotion; when absent the busts are used. */
  scene?: string[]
}

export interface LibraryBackground {
  id: string
  name: Localized
}

export interface LibraryManifest {
  version: number
  characters: LibraryCharacter[]
  avatars: string[]
  backgrounds: LibraryBackground[]
}

const SCENARIO_EMOTIONS: ScenarioEmotion[] = ['neutral', 'happy', 'concerned']

export function libraryUrl(path: string): string {
  return `${import.meta.env.BASE_URL}library/${path}`
}

let cached: Promise<LibraryManifest> | null = null

export function loadLibrary(): Promise<LibraryManifest> {
  cached ??= fetch(libraryUrl('manifest.json'))
    .then((r) => {
      if (!r.ok) throw new Error(`library manifest: ${r.status}`)
      return r.json() as Promise<LibraryManifest>
    })
    .catch((err) => {
      cached = null // let the next open retry
      throw err
    })
  return cached
}

async function importImage(path: string): Promise<string> {
  const res = await fetch(libraryUrl(path))
  if (!res.ok) throw new Error(`library file ${path}: ${res.status}`)
  const blob = await res.blob()
  const name = path.split('/').pop() ?? 'image.webp'
  return saveAsset(new File([blob], name, { type: 'image/webp' }), 'image')
}

/** Copies a character's pictures into the project. `scene` takes the waist-up
 *  poses (falling back to the busts until they exist in the library). */
export async function importCharacter(
  c: LibraryCharacter,
  scene: boolean,
): Promise<Partial<Record<ScenarioEmotion, string>>> {
  const poses = scene && c.scene?.length ? c.scene : c.emotions
  const prefix = scene && c.scene?.length ? 'scene-' : ''
  const out: Partial<Record<ScenarioEmotion, string>> = {}
  for (const emotion of SCENARIO_EMOTIONS) {
    if (poses.includes(emotion)) out[emotion] = await importImage(`characters/${c.id}/${prefix}${emotion}.webp`)
  }
  return out
}

export const importAvatar = (id: string) => importImage(`avatars/${id}.webp`)
export const importBackground = (id: string) => importImage(`backgrounds/${id}.webp`)
